/* data/concepts.js */
/* MEANING NODES — the definition store. ALL 431 NOUNS, 03 Sep 2026.

   1199 nodes, MN-0001 to MN-1199, no gaps and no duplicate slug. Steven's
   semantic pass, transcribed verbatim in five batches and checked against
   data/nouns.js: the 431 headwords appear in the same order with nothing
   missing and nothing extra. German definitions merged in two batches,
   Russian in one — see WHAT IS MISSING at the foot of this header.

   ------------------------------------------------------------------
   THE CONCEPT IS THE DEFINITION. THE WORD IS NOT.

   Steven's framing, and the file is built on it. A node owns a meaning.
   Words in any language are MEMBERS of it. There is no word-to-word
   mapping anywhere in this file and there must never be one — because
   words in different languages map to DIFFERENT SETS of meanings, and
   two words overlap only across the subset of nodes they happen to share.

   `die Bank` sits in five nodes. English `bank` would sit in some of them
   and not others. Translating `die Bank` as `bank` is right in exactly
   those nodes and wrong everywhere else, and only a per-node membership
   list can say which is which.

   ------------------------------------------------------------------
   TWENTY-FIVE NODES ALREADY HAVE MORE THAN ONE GERMAN MEMBER

     transport-elevator     der Aufzug · der Fahrstuhl
     clothing-outfit        der Anzug · der Aufzug · die Toilette
     geography-sea          das Meer · der See
     hardware-nut           die Mutter · die Nuss
     protective-screen      der Bildschirm · der Schirm
     ... and twenty more

   That is rule 3 doing the work, WITHIN one language. `der Aufzug` is a
   member of four nodes and shares two of them with different words. No
   arrangement where a word owns its senses can express that.

   ------------------------------------------------------------------
   IDS ARE ASSIGNED BY FIRST APPEARANCE AND NEVER RENUMBERED

   Rule 10. A new slug takes the next free number; an existing slug gains a
   member and keeps its id. NEVER re-sort this file and never renumber it.

   The slug is a human-readable handle, not the meaning and not a key to
   join on. It is English-flavoured because the pass was written in
   English; `id` is what anything else should reference.

   ------------------------------------------------------------------
   FOUR NODES SPLIT, TWO KEPT MERGED — Steven, 03 Sep

   Rule 4: merge only when MEANINGS match, not when wording overlaps. Six
   nodes had collided on words whose meanings were not identical. Steven
   ruled on all six.

   SPLIT:

     body-head              der Kopf            the literal organ
     slang-head             die Dose · die Birne · der Kopf
                            the head referred to informally

     astronomy-star         der Stern           any luminous body
     astronomy-system-sun   die Sonne           a system's central star

     container-beaker-cup   der Becher          typically WITHOUT a handle
     container-handled-cup  die Tasse           typically WITH one

     geography-mountain-crest  der Kamm         the highest line
     geography-land-ridge      der Rücken       the whole landform

   The Becher/Tasse distinction is semantically real, not cosmetic, and the
   Kamm/Rücken one is the crest against the landform that carries it.

   THE HEAD SPLIT LANDED SOMEWHERE USEFUL. `slang-head` already existed at
   MN-0185, from `die Dose`. Splitting `body-head` did not create a node —
   it fed an existing one, and `die Dose`, `die Birne` and `der Kopf` now
   sit together where they belong. `der Kopf` is a member of BOTH, because
   a word can be used literally and jokingly and both are true of it.

   KEPT MERGED, with the restriction recorded as `usage` rather than forced
   into a second meaning — Steven's ruling, and it is where it belongs:

     geography-sea   das Meer · der See    See carries the sea sense only
                                           in names and compounds
     food-table      die Tafel · der Tisch Tafel is the formal register

   STILL OPEN: `quantity-cupful` (MN-0087) holds both `der Becher` and
   `die Tasse`. The containers are now two nodes; whether the AMOUNTS they
   hold are also two meanings has not been ruled on.

   Its definition now reads "die Menge, die in ein kleines Trinkgefäß
   dieser Art passt" — vague on purpose, because it has to cover both
   members while the question is open. If Steven splits it, the halves
   can each be said plainly and this wording should be replaced, not
   inherited by either half.

   ------------------------------------------------------------------
   ON REUSING AN ID WHEN A NODE SPLITS

   MN-0086, MN-0117, MN-0467 and MN-0926 kept their ids and had their
   definitions corrected; the halves that needed somewhere new took
   MN-1197 to MN-1199. That is safe ONLY because nothing references these
   ids yet. Once anything does — a lesson, a saved answer, an export — an
   id's meaning is frozen and a split must mint two new ids and retire the
   old one. Rule 10 exists for the day after this one.

   ------------------------------------------------------------------
   WHERE TWO WORDS GAVE THE SAME NODE DIFFERENT WORDING

   Twelve nodes arrived with two wordings — `between levels` against
   `between floors`, `a commercial organization` against `a commercial
   enterprise`. Rule 1 says one node is one meaning, so they are merged on
   the FIRST-SEEN wording and the alternative is recorded in `alt` rather
   than thrown away. Steven has not picked between them.

   ------------------------------------------------------------------
   `check:'rule6'` — A DEFINITION THAT USES ITS OWN WORD

   Rule 6: never use the target word, a compound of it, or an inflected
   form in its own definition. It is the easiest rule to break when
   TRANSLATING a definition rather than writing one, because the English
   often names the thing harmlessly and the German then names it in the
   language being learned:

     death-end        das Ende      "das ENDE des Lebens einer Person"
     quantity-canful  die Dose      "die Menge, die in eine DOSE passt"
     plant-bean       die Bohne     "eine Pflanze, die BOHNEN bildet"
     profession-farmer der Bauer    "besitzt einen BAUERNHOF"   (compound)
     screen-image     das Bild      "auf einem BILDSCHIRM"      (compound)

   For a learner this is the difference between a definition and a
   circularity: she is looking the word up because she does not know it.

   Every node whose German definition contains one of its own members —
   whole, inflected, or inside a compound — carries `check:'rule6'`. The
   definition is kept, because a flawed definition is more useful than an
   empty one and the flag makes it findable.

   54 nodes carry the flag, out of the 641 that have German. The first
   batch of 240 tripped it 40 times, about one in six. The second batch
   of 401 tripped it 14 times, about one in twenty-nine — the writing
   got markedly cleaner. Four of the 54 are compounds a token check
   misses and only a substring check finds: E-Mail inside `E-Mail-System`,
   Schirm inside `Fallschirms`, Decke inside `bedeckt`, Schlüssel inside
   `verschlüsselt`.

   THE RUSSIAN SIDE HAS NEVER BEEN CHECKED AGAINST RULE 6 AND CANNOT BE
   YET. Rule 6 tests a definition against its own MEMBERS, and every
   member in this file is German. Some Russian definitions plainly name
   the Russian word — `quantity-cupful` said "помещается в чашку". Those
   are harmless while `members.ru` is empty and become violations the day
   it is not. Run the same substring pass over Russian the moment Russian
   members land. Same for English.

   ------------------------------------------------------------------
   THREE NODES ARRIVED TWICE, WITH DIFFERENT WORDING

   `clothing-outfit` (MN-0025), `quantity-cupful` (MN-0087) and
   `protective-screen` (MN-0114) came in both the first batch and the
   second, worded differently each time.

   Rule 1 — one node is one meaning — so one wording wins and the other
   is not kept as a second definition. FIRST-SEEN WINS, except where the
   later wording fixes a rule violation:

     clothing-outfit     kept first-seen
     protective-screen   kept first-seen
     quantity-cupful     REPLACED — the first German named `Tasse`, its
                         own member, and the second did not

   When a definition is swapped, EVERY language on that node is swapped
   with it. `quantity-cupful` took the second German AND the second
   Russian, because `def` holds one meaning written across three
   languages and mixing batches inside one node breaks exactly that.

   ------------------------------------------------------------------
   WHAT IS MISSING — AS OF 03 SEP 2026, AND THE WORK IS SHELVED HERE

     German definitions   641 of 1199   (558 empty)
     Russian definitions  641 of 1199   (558 empty)
     English members        0 of 1199
     Russian members        0 of 1199

   German and Russian cover the SAME 641 nodes — every node that has one
   has the other, and no node has only one. That symmetry is a property
   worth preserving and worth checking after any future merge.

   Steven shelved the rest to deploy Tanya's site. This is a nice-to-have
   that pays off later across languages, not a blocker for the German
   site. Do not resume it unasked.

   The model requires `def` to hold translations of ONE meaning rather
   than three independently chosen glosses, so they have to be written
   against each other. No German or Russian was drafted here — all of it
   is Steven's, transcribed verbatim.

   Members carry their article, per Steven's override of GPT's rule 7.

   ------------------------------------------------------------------
   HOW TO ADD TO THIS FILE WITHOUT BREAKING IT

   This file will be built on massively. Every one of these is a rule,
   not a suggestion, and every one of them exists because getting it
   wrong silently corrupts the file rather than throwing an error.

   1  MERGE BY SLUG. NEVER BY POSITION, NEVER BY LINE NUMBER, NEVER BY
      ORDER OF ARRIVAL. A batch that looks like it is in file order is
      the most dangerous input there is, because an off-by-one puts every
      definition on the wrong node and nothing complains.

   2  A SLUG IN THE INCOMING BATCH THAT IS NOT ALREADY IN THIS FILE IS AN
      ERROR UNTIL PROVEN OTHERWISE. Models invent slugs. Across the 799
      slugs sent out in the first round exactly one came back invented
      (`slang-head-container`). Diff the incoming slug list against the
      slugs here BEFORE writing anything, and resolve every mismatch by
      hand. Do not create a node to make a batch fit.

   3  NEVER OVERWRITE A NON-EMPTY FIELD SILENTLY. Fill empty strings.
      If a field already holds text and the batch disagrees, stop and
      report it — that is how the three double-arrivals above were
      caught.

   4  IDS ARE ASSIGNED BY FIRST APPEARANCE AND NEVER RENUMBERED (rule 10).
      A genuinely new node takes the next free number and goes at the end.
      Nothing above it moves. Renumbering is unrecoverable.

   5  CHECK AFTER EVERY MERGE, not just before:
        - node count, and the id sequence MN-0001..MN-NNNN with no gap
        - no duplicate id, no duplicate slug
        - every node has a non-empty def.en
        - de-count equals ru-count if the symmetry above still holds
        - the file loads: `node -e "global.window=global;require('./concepts.js')"`

   6  SNAPSHOT THE FILE BEFORE A MERGE. Two minutes of work protects
      hours of Steven's transcription.

   NOTHING READS THIS FILE YET. PENDING in audit.sh, not in index.html. */



